import { JSX, ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

const TicketBoxComponent: ParentComponent<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`img-ticket-solid-shadow-container ${props.class ?? ""}`}
		>
			{props.children}
		</div>
	);
};

export const TicketBox = ComponentRegistry.register({
	name: "TicketBox",
	createInstance: TicketBoxComponent,
	images: ["blp:ticket_solid_shadow"],
});
